create extension if not exists pgcrypto;

create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique,created_at timestamptz not null default now(),constraint username_format check(username ~ '^[a-z0-9_.]{3,24}$'));
create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 1 and 40),code text not null unique,created_by uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.room_members(room_id uuid not null references public.rooms(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(room_id,user_id));
create table if not exists public.media(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,file_path text not null unique,media_type text not null,view_limit int not null default 1 check(view_limit in(0,1,2)),view_count int not null default 0,created_at timestamptz not null default now());
create table if not exists public.messages(id bigint generated by default as identity primary key,room_id uuid not null references public.rooms(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text check(body is null or char_length(body)<=4000),media_id uuid references public.media(id) on delete set null,created_at timestamptz not null default now(),constraint message_has_content check(nullif(trim(coalesce(body,'')),'') is not null or media_id is not null));
create table if not exists public.room_invites(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,inviter_id uuid not null references public.profiles(id) on delete cascade,invitee_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(room_id,invitee_id));
alter table public.messages add column if not exists media_id uuid references public.media(id) on delete set null;

create index if not exists messages_room_created_idx on public.messages(room_id,created_at);
create index if not exists room_members_user_idx on public.room_members(user_id);
create index if not exists media_room_idx on public.media(room_id);

create or replace function public.make_room_code() returns text language plpgsql security definer set search_path=public as $$declare c text;begin loop c:=upper(substr(md5(random()::text||clock_timestamp()::text),1,8));exit when not exists(select 1 from rooms where code=c);end loop;return c;end$$;
create or replace function public.is_room_member(rid uuid) returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from room_members where room_id=rid and user_id=auth.uid())$$;
create or replace function public.create_room(room_name text) returns uuid language plpgsql security definer set search_path=public as $$declare r uuid;begin if auth.uid() is null then raise exception 'Not signed in';end if;if not exists(select 1 from profiles where id=auth.uid()) then raise exception 'Profile not found';end if;insert into rooms(name,code,created_by) values(trim(room_name),make_room_code(),auth.uid()) returning id into r;insert into room_members values(r,auth.uid(),now());return r;end$$;
create or replace function public.join_room_by_code(room_code_input text) returns uuid language plpgsql security definer set search_path=public as $$declare r uuid;begin select id into r from rooms where code=upper(trim(room_code_input));if r is null then raise exception 'Room code not found';end if;insert into room_members(room_id,user_id) values(r,auth.uid()) on conflict do nothing;return r;end$$;
create or replace function public.remove_room_member(room_id_input uuid,user_id_input uuid) returns boolean language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from rooms where id=room_id_input and created_by=auth.uid()) then raise exception 'Only the room owner can remove members';end if;if user_id_input=auth.uid() then raise exception 'Owner cannot remove themselves';end if;delete from room_members where room_id=room_id_input and user_id=user_id_input;return true;end$$;

-- Atomically consumes one view. A production Edge Function should call this and then create a 60-second signed URL.
create or replace function public.consume_media_view(media_id_input uuid) returns json language plpgsql security definer set search_path=public as $$declare m media;remain int;begin select * into m from media where id=media_id_input for update;if not found then raise exception 'Media not found';end if;if not is_room_member(m.room_id) then raise exception 'Not a room member';end if;if m.view_limit<>0 and m.view_count>=m.view_limit then return json_build_object('path',null,'remaining',0);end if;update media set view_count=view_count+1 where media.id=media_id_input returning * into m;remain=case when m.view_limit=0 then null else greatest(0,m.view_limit-m.view_count) end;return json_build_object('path',m.file_path,'remaining',remain,'media_type',m.media_type);end$$;

grant execute on function public.create_room(text) to authenticated;
grant execute on function public.join_room_by_code(text) to authenticated;
grant execute on function public.remove_room_member(uuid,uuid) to authenticated;
grant execute on function public.consume_media_view(uuid) to authenticated;

alter table profiles enable row level security;alter table rooms enable row level security;alter table room_members enable row level security;alter table messages enable row level security;alter table media enable row level security;alter table room_invites enable row level security;
drop policy if exists "profiles are viewable by signed in users" on profiles;create policy "profiles are viewable by signed in users" on profiles for select to authenticated using(true);
drop policy if exists "users create their own profile" on profiles;create policy "users create their own profile" on profiles for insert to authenticated with check(id=auth.uid());
drop policy if exists "members can view rooms" on rooms;create policy "members can view rooms" on rooms for select to authenticated using(is_room_member(id));
drop policy if exists "members can view room members" on room_members;drop policy if exists "users can join rooms" on room_members;create policy "members can view room members" on room_members for select to authenticated using(is_room_member(room_id));create policy "users can join rooms" on room_members for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "members can read messages" on messages;drop policy if exists "members can send messages" on messages;create policy "members can read messages" on messages for select to authenticated using(is_room_member(room_id));create policy "members can send messages" on messages for insert to authenticated with check(sender_id=auth.uid() and is_room_member(room_id));
drop policy if exists "members can read media" on media;drop policy if exists "members can create media" on media;create policy "members can read media" on media for select to authenticated using(is_room_member(room_id));create policy "members can create media" on media for insert to authenticated with check(sender_id=auth.uid() and is_room_member(room_id));
drop policy if exists "members create invites" on room_invites;drop policy if exists "invitees read invites" on room_invites;drop policy if exists "invitees delete invites" on room_invites;create policy "members create invites" on room_invites for insert to authenticated with check(inviter_id=auth.uid() and is_room_member(room_id));create policy "invitees read invites" on room_invites for select to authenticated using(invitee_id=auth.uid() or inviter_id=auth.uid());create policy "invitees delete invites" on room_invites for delete to authenticated using(invitee_id=auth.uid());

insert into storage.buckets(id,name,public) values('chat-media','chat-media',false) on conflict(id) do update set public=false;
drop policy if exists "users upload own chat media" on storage.objects;create policy "users upload own chat media" on storage.objects for insert to authenticated with check(bucket_id='chat-media' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "users delete own chat media" on storage.objects;create policy "users delete own chat media" on storage.objects for delete to authenticated using(bucket_id='chat-media' and owner_id=auth.uid()::text);

do $$begin alter publication supabase_realtime add table public.messages;exception when duplicate_object then null;end$$;
do $$begin alter publication supabase_realtime add table public.room_invites;exception when duplicate_object then null;end$$;
